//#############################################################################
//# Function: Positive edge-triggered static D-type flop-flop                 #

//# Copyright: OH Project Authors. ALl rights Reserved.                       #
//# License:  MIT (see LICENSE file in OH repository)                         # 
//#############################################################################

module oh_dffq #(parameter DW = 1) // array width
   (
    input [DW-1:0] 	d,
    input [DW-1:0] 	clk,
    output reg [DW-1:0] q
    );

   always @ (posedge clk)
     q <= d;

endmodule

//#############################################################################
//# Function:  Positive edge-triggered static D-type flop-flop with async     #
//#            active low reset.                                              # 
//#                                                                           #
//# Copyright: OH Project Authors. All rights Reserved.                       #
//# License:   MIT (see LICENSE file in OH repository)                        # 
//#############################################################################

module oh_dffrq #(parameter DW = 1) // array width
   (
    input [DW-1:0] 	d,
    input [DW-1:0] 	clk,
    input [DW-1:0] 	nreset,
    output reg [DW-1:0] q
    );

   always @ (posedge clk or negedge nreset)
     if(!nreset)
       q <= 'b0;
     else
       q <= d;

endmodule

//#############################################################################
//# Function:  Positive edge-triggered static inverting D-type flop-flop with #
//             async active low reset.                                        # 
//# Copyright: OH Project Authors. ALl rights Reserved.                       #
//# License:   MIT (see LICENSE file in OH repository)                        # 
//#############################################################################

module oh_dffrqn #(parameter DW = 1) // array width
   (
    input [DW-1:0] 	d,
    input [DW-1:0] 	clk,
    input [DW-1:0] 	nreset,
    output reg [DW-1:0] qn
    );

   always @ (posedge clk or negedge nreset)
     if(!nreset)
       qn <= {DW{1'b1}};
     else
       qn <= ~d;

endmodule

//#############################################################################
//# Function:  Positive edge-triggered static D-type flop-flop with async     #
//#            active low preset.                                             # 
//# Copyright: OH Project Authors. ALl rights Reserved.                       #
//# License:   MIT (see LICENSE file in OH repository)                        # 
//#############################################################################

module oh_dffsq #(parameter DW = 1) // array width
   (
    input [DW-1:0]     d,
    input [DW-1:0]     clk,
    input [DW-1:0]     nset,
    output reg [DW-1:0] q
    );

   always @ (posedge clk or negedge nset)
     if(!nset)
       q <= {DW{1'b1}};
     else
       q <= d;

endmodule

//#############################################################################
//# Function:  D-type active-high transparent latch                           #
//#                                                                           #
//# Copyright: OH Project Authors. ALl rights Reserved.                       #
//# License:   MIT (see LICENSE file in OH repository)                        # 
//#############################################################################

module oh_latq #(parameter DW = 1) // array width
   (
    input [DW-1:0] 	d,
    input [DW-1:0] 	g,
    output reg [DW-1:0] q
    );

   always_latch
     if(g)
       q <= d;

endmodule

//#############################################################################
//# Function: Rising Edge Sampled Register                                    #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_reg1
  #(parameter N    = 1,        // vector width
    parameter SYN  = "TRUE",   // synthesizable (or not)
    parameter TYPE = "DEFAULT" // scell type/size
    )
   ( input          nreset, //async active low reset
     input 	    clk,    // clk
     input 	    en,     // write enable
     input [N-1:0]  in,     // input data
     output [N-1:0] out     // output data (stable/latched when clk=1)
     );

   //TODO: Implement all classes of flip-flops
   generate
      if(SYN == "TRUE") begin
	 reg [N-1:0]      out_reg;
	 always @ (posedge clk or negedge nreset)
	   if(!nreset)
	     out_reg[N-1:0] <= 'b0;
	   else if(en)
	     out_reg[N-1:0] <= in[N-1:0];
	 assign out[N-1:0] = out_reg[N-1:0];
      end
      else begin
	 genvar 	     i;
	 for (i=0;i<N;i=i+1) begin
	    asic_reg1 #(.TYPE(TYPE))
	    asic_reg1  (// Outputs
			.out	(out[i]),
			// Inputs
			.nreset	(nreset),
			.clk	(clk),
			.en	(en),
			.in	(in[i]));
	 end
      end
   endgenerate
endmodule

//#############################################################################
//# Function: Negative edge-triggered static D-type flop-flop                 #
//# Copyright: OH Project Authors. ALl rights Reserved.                       #
