module oh_dffqn #(parameter DW = 1) // array width
   (
    input [DW-1:0] 	d,
    input [DW-1:0] 	clk,
    output reg [DW-1:0] qn
    );

   always @ (posedge clk)
     qn <= ~d;

endmodule

//#############################################################################
//# Function:  Positive edge-triggered static inverting D-type flop-flop with #
